import java.text.*;

class Student{
    private int roll_num;
    private Date dose_one = new Date();
    private Date dose_two = new Date();

    public int getRollNo() {
        return roll_num;
    }
    public Student(int roll_num, String dd_str) {
        SimpleDateFormat sdf = new SimpleDateFormat("dd/MM/yyyy");
        this.roll_num = roll_num;
        try {
            dose_one = sdf.parse(dd_str);
            dose_two = sdf.parse("30/03/2022");
        }
        catch(ParseException e){
            System.out.println("Incorrect Date Format");
        }
    }
    public boolean isEligible() {
        // █ FILLED BY STUDENT: return true if 28 or more days have passed between dose_one and dose_two
        long diffDays = (dose_two.getTime() - dose_one.getTime()) / (1000L * 60 * 60 * 24);
        return diffDays >= 28;
    }
}

