    public void removeLongDurationSongs(LinkedHashMap<Integer,Song> playlist) {
        Iterator<Map.Entry<Integer,Song>> it = playlist.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<Integer,Song> entry = it.next();
            if (isLongDuration(entry.getValue().getDuration())) it.remove();
        }
    }

