import math

def det_2x2(m) -> float:
    # █ FILLED BY STUDENT: Given a polygon as an ordered list of (x,y) vertices, implement perimeter, bounding_box, area (shoel…
    a, b, c, d = *m[0], *m[1]
    return a*d - b*c

def distance(p1, p2) -> float:
    x1, y1, x2, y2 = *p1, *p2
    return math.sqrt((x1-x2)**2 + (y1-y2)**2)

def zcross(A, B, C):
    ax, ay, bx, by, cx, cy = *A, *B, *C
    ab = (bx-ax, by-ay)
    bc = (cx-bx, cy-by)
    return det_2x2([ab, bc])

def perimeter(points: list) -> float:
    n = len(points)
    return sum(distance(points[i], points[(i+1) % n]) for i in range(n))

def bounding_box(points: list) -> tuple:
    xs = [p[0] for p in points]
    ys = [p[1] for p in points]
    return (min(xs), min(ys)), (max(xs), max(ys))

def area(points: list):
    n = len(points)
    return abs(sum(det_2x2([points[i], points[(i+1) % n]])
                   for i in range(n))) / 2

def is_convex(points: list) -> bool:
    n = len(points)
    return all(zcross(points[i], points[(i+1) % n], points[(i+2) % n]) > 0
               for i in range(n))

