class Library {
    private HashMap<String, Book> books;

    // █ FILLED BY STUDENT: initialise the books map
    public Library() {
        this.books = new LinkedHashMap<String, Book>();
    }

    public void addBook(Book book) {
        String key = book.getTitle() + "-" + book.getAuthor();
        books.put(key, book);
    }

    // █ FILLED BY STUDENT: return the list of books in the given genre
    public List<Book> searchByGenre(String genre) {
        List<Book> booksByGenre = new ArrayList<Book>();
