def min_cost(m, n, grid_costs):
    # █ FILLED BY STUDENT: Implement min_cost
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = grid_costs[0][0]
    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + grid_costs[0][j]
    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + grid_costs[i][0]
    for i in range(1, m):
